#include "config.h"
#include <assert.h>
#include <bitcoin/chainparams.h>
#include <ccan/str/hex/hex.h>
#include <common/setup.h>
#include <stdio.h>
#include <string.h>

/* AUTOGENERATED MOCKS START */
/* AUTOGENERATED MOCKS END */

/* The fee asset (L-BTC) of each Elements network.  elements-cli prints an
 * asset id byte-reversed; chainparams (and the wire) hold the internal order,
 * after a 0x01 "explicit" prefix.  A mix-up only shows on the real network:
 * lightningd's own L-BTC outputs get the wrong asset and elementsd rejects the
 * tx with bad-txns-in-ne-out. */
static void check_fee_asset(const char *network, const char *printed_id)
{
	const struct chainparams *p = chainparams_for_network(network);
	u8 id[32];

	assert(p);
	assert(p->is_elements);
	assert(p->fee_asset_tag);
	assert(hex_decode(printed_id, strlen(printed_id), id, sizeof(id)));
	assert(p->fee_asset_tag[0] == 0x01);
	for (size_t i = 0; i < sizeof(id); i++)
		assert(p->fee_asset_tag[1 + i] == id[sizeof(id) - 1 - i]);
}

int main(int argc, char *argv[])
{
	common_setup(argv[0]);

	check_fee_asset("liquid",
			"6f0279e9ed041c3d710a9f57d0c02928416460c4b722ae3457a11eec381c526d");
	check_fee_asset("liquid-regtest",
			"ceb851388a62039c49710566bc8b0b229eaa8a92bafbca512d8f7fd363b9e75c");
	check_fee_asset("liquid-testnet",
			"144c654344aa716d6f3abcc1ca90e5641e4e2a7f633bc09fe3baf64585819a49");

	common_shutdown();
	return 0;
}
